import { Controller, Delete, Get, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const BOX_TYPES = ['내 문서함', '공유한 문서', '공유받은 문서'];
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const ID_PATTERN = /^\d+$/;

function textOf(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

function idOf(value: unknown): string {
  const text = typeof value === 'string' ? value : '';
  if (!ID_PATTERN.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '경로의 ID 형식이 올바르지 않습니다.');
  }
  return text;
}

@Controller('api/v1')
export class FnSfr04103Controller {
  @Get('/office-documents')
  async listOfficeDocuments(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const boxType = textOf(query['boxType']);
    if (boxType === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '문서함 구분을 선택해 주세요.');
    }
    if (!BOX_TYPES.includes(boxType)) {
      throw new ApiError(422, 'INVALID_DOCUMENT_BOX_TYPE', '문서함 구분이 올바르지 않습니다.');
    }
    const title = textOf(query['title']);
    const createdFrom = textOf(query['createdFrom']);
    const createdTo = textOf(query['createdTo']);
    if (title.length > 300) {
      throw new ApiError(400, 'VALIDATION_FAILED', '문서 제목은 300자 이내로 입력해 주세요.');
    }
    if (createdFrom !== '' && !DATE_PATTERN.test(createdFrom)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '작성일 시작 형식이 올바르지 않습니다.');
    }
    if (createdTo !== '' && !DATE_PATTERN.test(createdTo)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '작성일 종료 형식이 올바르지 않습니다.');
    }
    const pageText = textOf(query['page']);
    const sizeText = textOf(query['size']);
    if ((pageText !== '' && !ID_PATTERN.test(pageText)) || (sizeText !== '' && !ID_PATTERN.test(sizeText))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기는 숫자여야 합니다.');
    }
    const page = pageText === '' ? 0 : Number(pageText);
    const size = Math.min(MAX_SIZE, Math.max(1, sizeText === '' ? DEFAULT_SIZE : Number(sizeText)));

    let from = 'office_document d';
    let where = 'd.author_id = CAST(:userId AS bigint)';
    let permissionColumn = 'CAST(NULL AS varchar)';
    let shareIdColumn = 'CAST(NULL AS bigint)';
    if (boxType !== '내 문서함') {
      from = 'office_document d JOIN office_document_share s ON s.office_document_id = d.office_document_id';
      permissionColumn = 's.permission_type';
      shareIdColumn = 's.office_document_share_id';
      if (boxType === '공유받은 문서') {
        where = 's.shared_employee_id = CAST(:userId AS bigint) AND s.hidden_by_recipient = false';
      }
    }
    const params: Record<string, unknown> = { userId: user.id };
    if (title !== '') {
      where += ' AND d.title LIKE :title';
      params['title'] = '%' + title + '%';
    }
    if (createdFrom !== '') {
      where += ' AND d.created_at >= CAST(:createdFrom AS date)';
      params['createdFrom'] = createdFrom;
    }
    if (createdTo !== '') {
      where += ' AND d.created_at < CAST(:createdTo AS date) + 1';
      params['createdTo'] = createdTo;
    }

    return transaction(async (db) => {
      const totalRows = await db.query('SELECT COUNT(*) AS "total" FROM ' + from + ' WHERE ' + where, params);
      const total = Number(totalRows[0]['total']);
      // officeDocumentShareId는 공유 해제 호출에 필요해 추가한 필드다 (공유 문서함에서만 값이 있다).
      const items = await db.query(
        'SELECT d.office_document_id AS "officeDocumentId", d.title AS "title", d.author_id AS "authorId", '
          + 'd.created_at AS "createdAt", ' + permissionColumn + ' AS "permissionType", '
          + shareIdColumn + ' AS "officeDocumentShareId" '
          + 'FROM ' + from + ' WHERE ' + where
          + ' ORDER BY d.created_at DESC, d.office_document_id DESC LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { ...params, size, offset: page * size },
      );
      return { items, page, size, total };
    });
  }

  @Delete('/office-documents/:officeDocumentId')
  async deleteOfficeDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const officeDocumentId = idOf(req.params['officeDocumentId']);
    return transaction(async (db) => {
      const docs = await db.query(
        'SELECT author_id AS "authorId", CAST(:userId AS bigint) = author_id AS "isAuthor" FROM office_document WHERE office_document_id = CAST(:id AS bigint)',
        { id: officeDocumentId, userId: user.id },
      );
      if (docs.length === 0) {
        throw new ApiError(404, 'OFFICE_DOCUMENT_NOT_FOUND', '문서를 찾을 수 없습니다.');
      }
      if (docs[0]['isAuthor'] === true) {
        // 작성자 삭제: 공유 정보를 먼저 지우고 문서를 지운다.
        await db.execute(
          'DELETE FROM office_document_share WHERE office_document_id = CAST(:id AS bigint)',
          { id: officeDocumentId },
        );
        await db.execute(
          'DELETE FROM office_document WHERE office_document_id = CAST(:id AS bigint)',
          { id: officeDocumentId },
        );
        return {};
      }
      // 공유받은 사용자 삭제: 원본은 유지하고 노출만 제거한다.
      const shares = await db.query(
        'SELECT office_document_share_id AS "shareId", hidden_by_recipient AS "hidden" FROM office_document_share '
          + 'WHERE office_document_id = CAST(:id AS bigint) AND shared_employee_id = CAST(:userId AS bigint)',
        { id: officeDocumentId, userId: user.id },
      );
      if (shares.length === 0) {
        throw new ApiError(409, 'OFFICE_DOCUMENT_ACCESS_DENIED', '삭제 권한이 없는 문서입니다.');
      }
      if (shares[0]['hidden'] === true) {
        throw new ApiError(404, 'OFFICE_DOCUMENT_NOT_FOUND', '이미 삭제되었거나 공유 해제된 문서입니다.');
      }
      await db.execute(
        'UPDATE office_document_share SET hidden_by_recipient = true, updated_at = now() WHERE office_document_share_id = CAST(:shareId AS bigint)',
        { shareId: String(shares[0]['shareId']) },
      );
      return {};
    });
  }

  @Delete('/office-document-shares/:officeDocumentShareId')
  async deleteOfficeDocumentShare(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const shareId = idOf(req.params['officeDocumentShareId']);
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT CAST(:userId AS bigint) = d.author_id AS "isAuthor" FROM office_document_share s '
          + 'JOIN office_document d ON d.office_document_id = s.office_document_id '
          + 'WHERE s.office_document_share_id = CAST(:shareId AS bigint)',
        { shareId, userId: user.id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'OFFICE_DOCUMENT_SHARE_NOT_FOUND', '이미 공유 해제된 공유 정보입니다.');
      }
      if (rows[0]['isAuthor'] !== true) {
        throw new ApiError(409, 'OFFICE_DOCUMENT_SHARE_FORBIDDEN', '작성자만 공유를 해제할 수 있습니다.');
      }
      await db.execute(
        'DELETE FROM office_document_share WHERE office_document_share_id = CAST(:shareId AS bigint)',
        { shareId },
      );
      return {};
    });
  }
}

