import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  Num,
  Pager,
  RefName,
  Select,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;
const BOX_OPTIONS: [string, string][] = [
  ['내 문서함', '내 문서함'],
  ['공유한 문서', '공유한 문서'],
  ['공유받은 문서', '공유받은 문서'],
];

interface Target {
  kind: 'document' | 'share';
  row: Row;
}

export default function FnSfr04103Page({ role, notify }: PageProps) {
  const [boxType, setBoxType] = useState('내 문서함');
  const [title, setTitle] = useState('');
  const [createdFrom, setCreatedFrom] = useState('');
  const [createdTo, setCreatedTo] = useState('');
  const [applied, setApplied] = useState<Row>({ boxType: '내 문서함' });
  const [pageNo, setPageNo] = useState(0);
  const [target, setTarget] = useState<Target | null>(null);

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/office-documents', role, undefined, { ...applied, page: pageNo, size: SIZE }),
    [applied, pageNo],
  );

  const search = () => {
    setPageNo(0);
    setApplied({ boxType, title, createdFrom, createdTo });
  };

  const reset = () => {
    setBoxType('내 문서함');
    setTitle('');
    setCreatedFrom('');
    setCreatedTo('');
    setPageNo(0);
    setApplied({ boxType: '내 문서함' });
  };

  const submitDelete = async () => {
    if (!target) return;
    if (target.kind === 'document') {
      await call('DELETE', '/office-documents/' + String(target.row['officeDocumentId']), role);
      notify(applied['boxType'] === '공유받은 문서' ? '문서함에서 제거했습니다.' : '문서를 삭제했습니다.');
    } else {
      await call('DELETE', '/office-document-shares/' + String(target.row['officeDocumentShareId']), role);
      notify('공유를 해제했습니다.');
    }
    setTarget(null);
    reload();
  };

  const currentBox = String(applied['boxType']);
  const columns = [
    { key: 'title', label: '문서 제목' },
    {
      key: 'authorId',
      label: '작성자',
      render: (row: Row) => <RefName table="employee" role={role} value={row['authorId']} />,
    },
    {
      key: 'createdAt',
      label: '생성 일시',
      render: (row: Row) => <DateText value={row['createdAt']} time />,
    },
    {
      key: 'permissionType',
      label: '공유 권한',
      render: (row: Row) => (row['permissionType'] ? <Badge value={row['permissionType']} /> : <span>-</span>),
    },
    {
      key: 'actions',
      label: '처리',
      render: (row: Row) => (
        <span>
          {currentBox === '공유한 문서' ? (
            <button type="button" onClick={() => setTarget({ kind: 'share', row })}>
              공유 해제
            </button>
          ) : null}
          {currentBox !== '공유한 문서' ? (
            <button type="button" onClick={() => setTarget({ kind: 'document', row })}>
              {currentBox === '공유받은 문서' ? '목록에서 제거' : '삭제'}
            </button>
          ) : null}
        </span>
      ),
    },
  ];

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>조회 건수</h2>
        <p>{currentBox}</p>
        <h1>
          <Num value={data ? data.total : 0} />
        </h1>
      </section>
      <section className="box span-8">
        <h2>문서함</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="문서함 구분" required>
            <Select value={boxType} onChange={setBoxType} options={BOX_OPTIONS} />
          </Field>
          <Field label="문서 제목">
            <TextInput value={title} onChange={setTitle} />
          </Field>
          <Field label="작성일 시작">
            <DateInput value={createdFrom} onChange={setCreatedFrom} />
          </Field>
          <Field label="작성일 종료">
            <DateInput value={createdTo} onChange={setCreatedTo} />
          </Field>
        </Filters>
      </section>
      <section className="box span-12">
        <h2>문서 목록</h2>
        <Band total={data ? data.total : 0} />
        {error ? <p>{error}</p> : null}
        <DataTable columns={columns} rows={data ? data.items : []} empty="문서가 없습니다." />
        <Pager page={pageNo} size={SIZE} total={data ? data.total : 0} onPage={setPageNo} />
      </section>
      {target ? (
        <Drawer
          title={target.kind === 'share' ? '공유 해제' : currentBox === '공유받은 문서' ? '문서함에서 제거' : '문서 삭제'}
          onClose={() => setTarget(null)}
        >
          <Form
            onSubmit={submitDelete}
            submit={target.kind === 'share' ? '공유 해제' : '삭제'}
            danger
            note={
              target.kind === 'share'
                ? '공유를 해제하면 상대방의 공유받은 문서함에서 문서가 제외됩니다.'
                : currentBox === '공유받은 문서'
                  ? '원본 문서는 유지되고 내 문서함에서만 보이지 않게 됩니다.'
                  : '문서와 공유 정보가 삭제됩니다.'
            }
          >
            <Field label="문서 제목" wide>
              <span>{String(target.row['title'])}</span>
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
